// Agent Playground — test any agent with a prompt (SSE streaming)
app.post('/api/playground/run', rateLimit('heavy'), (req, res) => {
  const { agentName, prompt: userPrompt, customInstructions, timeoutMs } = req.body;
  if (!userPrompt) return res.status(400).json({ error: 'Prompt is required' });

  res.setTimeout(0);
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const send = (data) => {
    if (ended) return;
    try { res.write(`data: ${JSON.stringify(data)}\n\n`); } catch {}
  };

  // Load agent instructions
  let instructions = '';
  if (agentName) {
    const agentContentMap = {};
    const globalAgentsDir = path.join(CLAUDE_DIR, 'agents');
    if (fs.existsSync(globalAgentsDir)) {
      for (const file of fs.readdirSync(globalAgentsDir).filter(f => f.endsWith('.md'))) {
        const content = fs.readFileSync(path.join(globalAgentsDir, file), 'utf-8');
        const nameMatch = content.match(/^name:\s*(.+)$/m);
        const key = nameMatch ? nameMatch[1].trim() : file.replace('.md', '');
        agentContentMap[key] = content;
        agentContentMap[file.replace('.md', '')] = content;
      }
    }
    // Also check project agents
    const config = loadConfig();
    const projects = discoverProjects(config.projectDirs);
    for (const p of projects) {
      for (const a of (p.agents || [])) {
        agentContentMap[a.name] = a.body || a.raw;
        agentContentMap[a.filename] = a.body || a.raw;
      }
    }
    instructions = agentContentMap[agentName] || '';

    // Agent not found — warn the user
    if (!instructions) {
      send({ type: 'error', error: `Agent "${agentName}" not found in global or project agents` });
      res.end();
      return;
    }

    // Inject output template if agent has one
    try {
      const agentPath = path.join(CLAUDE_DIR, 'agents', agentName + '.md');
      if (fs.existsSync(agentPath)) {
        const { data: agentMeta } = matter(fs.readFileSync(agentPath, 'utf-8'));
        if (agentMeta.output_template) {
          const tmplPath = path.join(TEMPLATES_DIR, agentMeta.output_template + '.md');
          if (fs.existsSync(tmplPath)) {
            const { content: tmplBody } = matter(fs.readFileSync(tmplPath, 'utf-8'));
            instructions += '\n\n## OUTPUT FORMAT (MANDATORY)\nYou MUST structure your response exactly as follows. Do not deviate from this format.\n\n' + tmplBody.trim();
          }
        }
      }
    } catch {}

    // Inject training corrections if any
    try {
      const agentKey = agentName.replace(/\s.*$/, '').toLowerCase();
      const trainingFiles = [agentName, agentKey].map(n => path.join(TRAINING_DIR, n + '.json'));
      for (const tf of trainingFiles) {
        if (fs.existsSync(tf)) {
          const corrections = JSON.parse(fs.readFileSync(tf, 'utf-8')).filter(c => c.status === 'active');
          if (corrections.length > 0) {
            instructions += '\n\n## TRAINING CORRECTIONS (Follow these strictly)\n' +
              corrections.map((c, i) => `${i + 1}. [${c.timestamp.split('T')[0]}] ${c.correction}`).join('\n');
          }
          break;
        }
      }
    } catch {}
  }

  if (customInstructions) {
    instructions = customInstructions;
  }

  let fullPrompt = '';
  if (instructions) {
    fullPrompt = `${instructions}\n\n---\n\n## Task:\n${userPrompt}\n\n---\n\nIMPORTANT: Produce the actual deliverable directly. Do NOT write meta-commentary. Output only the finished work product.`;
  } else {
    fullPrompt = userPrompt;
  }

  const timeout = Math.min(timeoutMs ?? 120000, 600000); // max 10 min, ?? avoids 0 becoming falsy
  const claudePath = process.env.CLAUDE_PATH || 'claude';
  const childEnv = { ...process.env, HOME: os.homedir() };
  delete childEnv.CLAUDECODE;
  const proc = spawn(claudePath, ['-p'], { env: childEnv });
  let fullOutput = '';
  let killed = false;
  let ended = false; // Guard against double res.end()

  const finish = () => {
    if (ended) return;
    ended = true;
    try { res.end(); } catch {}
  };

  const timer = setTimeout(() => {
    killed = true;
    proc.kill('SIGTERM');
    setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
  }, timeout);

  const playgroundStartTime = Date.now();
  send({ type: 'start', agent: agentName || 'custom' });

  proc.stdout.on('data', (data) => {
    if (ended) return;
    const chunk = data.toString();
    fullOutput += chunk;
    try { send({ type: 'chunk', content: chunk }); } catch {}
  });

  proc.stderr.on('data', (data) => {
    if (ended) return;
    const msg = data.toString().trim();
    if (msg) {
      try { send({ type: 'activity', message: msg }); } catch {}
    }
  });

  proc.on('close', (code) => {
    clearTimeout(timer);
    if (ended) return;
    const runSource = req.body.source || 'playground';
    if (killed) {
      send({ type: 'error', error: `Timed out after ${timeout / 1000}s` });
      logAgentRun({ agentName: agentName || 'custom', prompt: userPrompt, output: '', source: runSource, duration: Date.now() - playgroundStartTime, status: 'error', error: `Timed out after ${timeout / 1000}s` });
    } else if (code !== 0 && !fullOutput.trim()) {
      send({ type: 'error', error: `Process exited with code ${code}` });
      logAgentRun({ agentName: agentName || 'custom', prompt: userPrompt, output: '', source: runSource, duration: Date.now() - playgroundStartTime, status: 'error', error: `Process exited with code ${code}` });
    } else {
      send({ type: 'done', output: fullOutput.trim() });
      logAgentRun({ agentName: agentName || 'custom', prompt: userPrompt, output: fullOutput.trim(), source: runSource, duration: Date.now() - playgroundStartTime, status: 'success' });
    }
    finish();
  });

  proc.on('error', (err) => {
    clearTimeout(timer);
    if (ended) return;
    send({ type: 'error', error: err.message });
    logAgentRun({ agentName: agentName || 'custom', prompt: userPrompt, output: '', source: req.body.source || 'playground', duration: Date.now() - playgroundStartTime, status: 'error', error: err.message });
    finish();
  });

  proc.stdin.write(fullPrompt, 'utf8');
  proc.stdin.end();

  // Handle client disconnect — kill the process
  req.on('close', () => {
    clearTimeout(timer);
    ended = true;
    if (!proc.killed) {
      proc.kill('SIGTERM');
      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 3000);
    }
  });
});

// ── Playground History CRUD ──────────────────────────────────────────────────
app.get('/api/playground/history', rateLimit('read'), (req, res) => {
  res.json(loadPlaygroundHistory());
});

app.post('/api/playground/history', rateLimit('write'), (req, res) => {
  const { id, agent, agentName, prompt, output, duration, status, timestamp } = req.body;
  if (!prompt) return res.status(400).json({ error: 'prompt is required' });
  const entry = {
    id: id || genId(),
    agent: agent || '',
    agentName: agentName || 'Unknown',
    prompt,
    output: (output || '').slice(0, 500000),
    duration: duration || 0,
    status: status || 'success',
    timestamp: timestamp || new Date().toISOString(),
  };
  const list = loadPlaygroundHistory();
  list.unshift(entry);
  savePlaygroundHistory(list);
  res.json(entry);
});

app.delete('/api/playground/history/:id', rateLimit('write'), (req, res) => {
  const list = loadPlaygroundHistory().filter(h => h.id !== req.params.id);
  savePlaygroundHistory(list);
  res.json({ ok: true });
});

app.delete('/api/playground/history', rateLimit('write'), (req, res) => {
  savePlaygroundHistory([]);

  if (!testPrompt) { toast('error', 'Enter a test prompt'); return }

  const agentToUse = overrideAgent ?? selectedAgent
  const resolvedAgent = allAgents.find(a => a.filename === agentToUse || a.name === agentToUse)
  setRunning(true)
  setOutput('')
  setActivityLog([])
  setElapsedMs(0)
  setActiveHistoryId(null)
  setShowRating(false)
  startTimeRef.current = Date.now()
  abortRef.current = new AbortController()

  try {
    const body: Record<string, unknown> = {
      agentName: agentToUse || undefined,
      prompt: testPrompt,
      timeoutMs: settings.timeoutMs,
    }
    if (settings.customInstructions.trim()) {
      body.customInstructions = settings.customInstructions.trim()
    }

    const response = await fetch('/api/playground/run', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      signal: abortRef.current.signal,
    })

    if (!response.ok) {
      const errText = await response.text().catch(() => `HTTP ${response.status}`)
      throw new Error(errText)
    }
    if (!response.body) throw new Error('No response body')
    const reader = response.body.getReader()
    const decoder = new TextDecoder()
    let buffer = ''
    let fullOutput = ''
    let hadError = false

    const processLine = (line: string) => {
      const trimmed = line.trim()
      if (!trimmed.startsWith('data: ')) return
      try {
        const event = JSON.parse(trimmed.slice(6))
        if (event.type === 'chunk') {
          fullOutput += event.content
          setOutput(fullOutput)
        } else if (event.type === 'activity') {
          const elapsed = Date.now() - startTimeRef.current
          setActivityLog(prev => [...prev.slice(-49), { message: event.message, time: elapsed }])
        } else if (event.type === 'done') {
          fullOutput = event.output || fullOutput
          setOutput(fullOutput)
        } else if (event.type === 'error') {
          fullOutput = `Error: ${event.error}`
          setOutput(fullOutput)
          hadError = true
        }
      } catch {}
    }

    while (true) {
      const { done, value } = await reader.read()
      if (done) break
      buffer += decoder.decode(value, { stream: true })
      const parts = buffer.split('\n')
      buffer = parts.pop() ?? ''
      for (const line of parts) processLine(line)
    }

    // Flush remaining buffer
    if (buffer.trim()) {
      for (const line of buffer.split('\n')) processLine(line)
    }

    const duration = Date.now() - startTimeRef.current
    const agentDisplay = resolvedAgent?.name || agentToUse || 'No Agent'
    const newItem: TestResult = {
      id: `${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
      agent: agentToUse || '',
      agentName: agentDisplay,
      prompt: testPrompt,
      output: fullOutput,
      duration,
      status: hadError ? 'error' : 'success',
      timestamp: new Date(),
    }

    setHistory(prev => [newItem, ...prev].slice(0, 50))
    savePlaygroundHistoryItem(toHistoryItem(newItem)).catch(() => {})

  } catch (err: unknown) {
    const duration = Date.now() - startTimeRef.current
    if (err instanceof Error && err.name === 'AbortError') {
      setOutput(prev => prev ? prev + '\n\n---\n*Test cancelled by user*' : 'Test cancelled.')
    } else {
      const errMsg = err instanceof Error ? err.message : String(err)
      setOutput(`Error: ${errMsg}`)
      const agentDisplay = resolvedAgent?.name || agentToUse || 'No Agent'
      const newItem: TestResult = {
        id: `${Date.now()}`,
        agent: agentToUse || '',
        agentName: agentDisplay,
        prompt: testPrompt,
        output: `Error: ${errMsg}`,
        duration,
        status: 'error',
        timestamp: new Date(),
      }
      setHistory(prev => [newItem, ...prev].slice(0, 50))
      savePlaygroundHistoryItem(toHistoryItem(newItem)).catch(() => {})
    }
  } finally {
    setRunning(false)
    abortRef.current = null
  }
}, [prompt, selectedAgent, settings, allAgents])

const cancelRun = () => { abortRef.current?.abort() }

// ─── Actions ──────────────────────────────────────────────────────────

const copyOutput = () => {
  navigator.clipboard.writeText(output)
  toast('success', 'Copied to clipboard')
}

const exportItem = (item?: TestResult) => {
  const exportPrompt = item?.prompt || prompt
  const exportOutput = item?.output || output
  const exportAgent = item?.agentName || currentAgent?.name || 'raw-prompt'
  if (!exportOutput) return
  const blob = new Blob([`# Playground Test: ${exportAgent}\n\n**Prompt:**\n${exportPrompt}\n\n**Output:**\n${exportOutput}`], { type: 'text/markdown' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = `playground-${exportAgent.toLowerCase().replace(/\s+/g, '-')}-${Date.now()}.md`
  a.click()
  URL.revokeObjectURL(url)
}

const loadFromHistory = (item: TestResult) => {
  setSelectedAgent(item.agent)
  setPrompt(item.prompt)
  setOutput(item.output)
  setActiveHistoryId(item.id)
  setShowRating(false)
}

