  const endStream = (eventData) => {
    if (responded) return;
    responded = true;
    res.write(`data: ${JSON.stringify(eventData)}\n\n`);
    res.end();
  };

  proc.on('close', (code, signal) => {
    if (code !== 0 || signal) {
      const errMsg = errOutput.trim() || 'Claude process failed';
      endStream({ type: 'error', error: errMsg });
    } else {
      endStream({ type: 'done', content: fullOutput.trim() });
    }
  });

  proc.on('error', (err) => {
    endStream({ type: 'error', error: err.message });
  });

  proc.stdin.write(prompt, 'utf8');
  proc.stdin.end();

  // Kill child process if client disconnects before it finishes
  const socket = req.socket;
  if (socket) {
    socket.on('close', () => {
      if (!responded) { try { proc.kill(); } catch {} }
    });
  }
});

